const body = $input.first().json.body || $input.first().json;
const lead = body.lead || body;
const bookingUrl = body.booking_url || 'https://meetings-ap1.hubspot.com/christopher-sparshott';
const browseUrl = body.browse_url || 'https://vendors.successbycs.com/browse';
const fallbackThankYou = body.thank_you_message || `Thanks for reaching out to SuccessByCS. Book time with Chris here: ${bookingUrl}`;
const intent = String(body.lead_intent || lead.lead_intent || body.intent || '').trim();
const intentLabels = {
  browse_directory: 'Browse the vendor directory',
  advisory_follow_up: 'Advisory follow-up with SuccessByCS',
  advisory: 'Advisory follow-up with SuccessByCS',
  shortlist: 'Shortlist brief',
};
const intentLabel = intentLabels[intent] || (intent || 'Lead capture');
const leadName = String(lead.lead_name || body.lead_name || body.name || 'there').trim() || 'there';
const leadEmail = String(lead.lead_email || body.lead_email || body.email || '').trim();
const companyName = String(lead.company_name || body.company_name || body.company || 'your team').trim() || 'your team';
const DISCORD_WEBHOOK_DEFAULT = 'https://discordapp.com/api/webhooks/1487579959714382075/W-HF3awATW1bx5XDGMC9O4Be7pBnT2MJS8TMPlrApnPa8iaqPK2eqiKTHBMn-kzknzbR';
const discordWebhook = String(body.discord_webhook_url || DISCORD_WEBHOOK_DEFAULT).trim();
const discordWebhookUrl = discordWebhook ? (discordWebhook.includes('?') ? `${discordWebhook}&wait=true` : `${discordWebhook}?wait=true`) : '';
const discordContent = body.discord_content || [
  'New CSP lead captured',
  `Lead: ${leadName}`,
  `Company: ${companyName}`,
  `Email: ${leadEmail}`,
  `Intent: ${intentLabel}`,
  `Book time with Chris: ${bookingUrl}`,
].join('\n');
const renderEmail = (paragraphs) => paragraphs.map((paragraph) => `<p style="margin:0 0 16px 0;line-height:1.6;font-family:Arial,sans-serif;color:#163320;font-size:16px;">${paragraph}</p>`).join('');
const signature = '<p style="margin:24px 0 0 0;line-height:1.6;font-family:Arial,sans-serif;color:#163320;font-size:16px;">Best,<br>Chris Sparshott<br>SuccessByCS<br><a href="mailto:chris@successbycs.com" style="color:#163320;">chris@successbycs.com</a></p>';
let emailSubject = 'Thanks for reaching out to SuccessByCS';
let emailMessage = renderEmail([
  `Hi ${leadName},`,
  'Thanks for reaching out to SuccessByCS.',
  `You can book time with me here: <a href="${bookingUrl}" style="color:#163320;">${bookingUrl}</a>`,
]) + signature;
if (intent === 'browse_directory') {
  emailSubject = 'Your SuccessByCS vendor directory access';
  emailMessage = renderEmail([
    `Hi ${leadName},`,
    `Thanks for requesting access to the SuccessByCS vendor directory for ${companyName}.`,
    `You can browse it here: <a href="${browseUrl}" style="color:#163320;">${browseUrl}</a>`,
    `If you want help interpreting the market or building a shortlist, book time with me here: <a href="${bookingUrl}" style="color:#163320;">${bookingUrl}</a>`,
  ]) + signature;
} else if (intent === 'advisory_follow_up') {
  emailSubject = 'Thanks for reaching out to SuccessByCS';
  emailMessage = renderEmail([
    `Hi ${leadName},`,
    `Thanks for reaching out to SuccessByCS. I received your advisory follow-up request for ${companyName}.`,
    `You can book time with me here: <a href="${bookingUrl}" style="color:#163320;">${bookingUrl}</a>`,
    'If useful, just reply to this email with your evaluation context, timeline, or current stack.',
  ]) + signature;
}
return [{ json: { lead_id: lead.lead_id || body.lead_id || '', lead_name: leadName, lead_email: leadEmail, company_name: companyName, lead_intent: intent, intent_label: intentLabel, thank_you_message: fallbackThankYou, booking_url: bookingUrl, browse_url: browseUrl, discord_webhook_url: discordWebhookUrl, discord_configured: Boolean(discordWebhookUrl), discord_content: discordContent, email_subject: emailSubject, email_message: emailMessage } }];
